    if isinstance(dir_path, str):
        # Check if the string is an S3 URL
        if parse.urlparse(dir_path).scheme == 's3':
            # If it's an S3 URL, extract the bucket and key from the URL
            bucket, key = parse.parse_qs(parse.urlparse(dir_path).query)['bucket'][0], parse.parse_qs(parse.urlparse(dir_path).query)['key'][0]
            # Create a new Dir instance with the S3 URL and the bucket and key as attributes
            return Dir(url=dir_path, path=f's3://{bucket}/{key}')

        # If it's not an S3 URL, assume it's a local path
        else:
            # Create a new Dir instance with the local path
            return Dir(path=dir_path)

    # If dir_path is neither a Dir instance nor a string, raise a ValueError
    else:
        raise ValueError('Invalid dir_path. It must be a Dir instance or a string.')
